package com.vaultorandroid
import android.util.Log
import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.platform.app.InstrumentationRegistry
import com.facebook.react.bridge.*
import org.json.*
import org.junit.Test
import org.junit.Assert.*
import org.junit.runner.RunWith
import java.io.File
import java.util.concurrent.*
@RunWith(AndroidJUnit4::class)
class ExportExperienceTest {
 init{require(android.os.Build.HARDWARE=="ranchu")}
 private val i get()=InstrumentationRegistry.getInstrumentation();private val ctx get()=i.targetContext;private val args get()=InstrumentationRegistry.getArguments();private val meta get()=File(ctx.cacheDir,"r89-live-export.json")
 private fun call(block:(PromiseImpl)->Unit):String {val latch=CountDownLatch(1);var value="";var failure="";block(PromiseImpl(Callback{value=it[0].toString();latch.countDown()},Callback{failure=it[0].toString();latch.countDown()}));assertTrue(latch.await(120,TimeUnit.SECONDS));assertTrue("Native request refused",failure.isEmpty());return value}
 private fun module()=VaultorModule(BridgeReactContext(ctx))
 private fun row(m:VaultorModule,id:String):JSONObject{val rows=JSONArray(call{m.companionExports("list","{}",it)});return (0 until rows.length()).map {rows.getJSONObject(it)}.single {it.getString("id")==id}}
 @Test fun pairStartCapturedExportSwitchSourceAndDieDuringDownload(){if(android.os.Build.VERSION.SDK_INT>=37)i.uiAutomation.grantRuntimePermission(ctx.packageName,android.Manifest.permission.ACCESS_LOCAL_NETWORK);val m=module();val boot=JSONObject(call{m.storage("bootstrap","{}",it)});val profiles=boot.getJSONArray("profiles");if(profiles.length()>=8){val old=(0 until profiles.length()).map {profiles.getJSONObject(it)}.first {it.getString("hostId")!=boot.optString("selected")&&it.getString("address").startsWith("https://127.0.0.1:")};call{m.signOut(old.getString("hostId"),it)}};val enrollment=JSONObject(call{m.beginPairing(args.getString("address")!!,it)});Log.i("VaultorR89Test","PAIR_CODE "+enrollment.getString("code"));var approved=false;repeat(120){if(!approved){approved=JSONObject(call{m.completePairing(it)}).optString("state")=="APPROVED";if(!approved)Thread.sleep(1000)}};assertTrue(approved);val host=enrollment.getString("hostId");var active=JSONObject(call{m.activate(host,it)});active=JSONObject(call{m.selectWorkspace(host,active.getString("epoch"),args.getString("workspaceId")!!,args.getString("generation")!!,it)});val scope=JSONArray(listOf(host,args.getString("workspaceId"),args.getString("generation"))).toString();val input=JSONObject().put("hostId",host).put("epoch",active.getString("epoch")).put("scope",scope).put("offline",false).put("label","R89 captured original source").put("request",JSONObject().put("scope","workspace").put("format","zip").put("ids",JSONArray()).put("depth",0));val export=JSONObject(call{m.companionExports("start",input.toString(),it)});val id=export.getString("id");call{m.selectWorkspace(host,active.getString("epoch"),args.getString("secondId")!!,args.getString("secondGeneration")!!,it)};meta.writeText(JSONObject().put("id",id).put("source",export.getJSONObject("source")).put("request",export.getJSONObject("request")).put("otherWorkspace",args.getString("secondId")).toString());val part=File(ctx.noBackupFilesDir,"exports-v1/$id.part");repeat(1000){if(part.length()>65536){Log.i("VaultorR89Test","EXPORT_DEATH_ID $id");android.os.Process.killProcess(android.os.Process.myPid());Thread.sleep(10000)};if(row(m,id).optString("state")=="error")fail(row(m,id).optString("detail"));Thread.sleep(5)};fail("Did not reach active export download death checkpoint")}
 @Test fun resumeExactExportWithInactiveSourceAfterDeathOrUpgrade(){val saved=JSONObject(meta.readText());val m=module();val id=saved.getString("id");val before=JSONObject(call{m.storage("bootstrap","{}",it)}).getString("epoch");call{m.companionExports("resume",JSONObject().put("id",id).toString(),it)};var row=row(m,id);repeat(1000){if(row.optString("state")!="ready"&&row.optString("state")!="error"){Thread.sleep(100);row=row(m,id)}};assertEquals(row.optString("detail"),"ready",row.getString("state"));assertEquals(saved.getJSONObject("source").toString(),row.getJSONObject("source").toString());assertEquals(saved.getJSONObject("request").toString(),row.getJSONObject("request").toString());assertEquals(before,JSONObject(call{m.storage("bootstrap","{}",it)}).getString("epoch"));val artifact=File(ctx.noBackupFilesDir,"exports-v1/$id.bin");val hash=java.security.MessageDigest.getInstance("SHA-256").digest(artifact.readBytes()).joinToString(""){"%02x".format(it)};assertEquals(row.getString("sha256"),hash);java.util.zip.ZipFile(artifact).use {zip->val manifest=JSONObject(zip.getInputStream(zip.getEntry("manifest.json")).bufferedReader().readText());assertEquals(5,manifest.getInt("version"))};Log.i("VaultorR89Test","EXPORT_ID $id SHA256 $hash")}
}
